/** Offline showcase: authored carton generated by the actual img2threejs factory. */
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { createOpenFoldingCartonModel } from './factory.ts';
import { certifyFoldSweep, sampleFold } from './hinge_sweep_collision.mjs';

const ids = ['back-flap', 'front-flap', 'left-flap', 'right-flap'];
const labels = {
  'back-flap': 'Back flap',
  'front-flap': 'Front flap',
  'left-flap': 'Left flap',
  'right-flap': 'Right flap',
};
const referencePose = { 'back-flap': 22, 'front-flap': -65,
  'left-flap': -24, 'right-flap': 32 };
const values = Object.fromEntries(ids.map(id => [id, 0]));
const root = createOpenFoldingCartonModel();
const runtime = root.userData.sculptRuntime;
const stage = document.getElementById('stage');
if (!runtime?.hinges || ids.some(id => !runtime.hinges[id] || !runtime.meshes[id])) {
  throw new Error('hinge lab requires the generated four-panel runtime');
}
document.getElementById('panel-count').textContent = String(ids.length);
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0f1724);
scene.add(root);
scene.add(new THREE.HemisphereLight(0xfaf5f1, 0x344059, 2.5));
const sun = new THREE.DirectionalLight(0xffffff, 2.6);
sun.position.set(4, 7, 5);
scene.add(sun);
const lightBack = new THREE.DirectionalLight(0xb7c8e8, 0.8);
lightBack.position.set(-3, 3, -6);
scene.add(lightBack);
const renderer = new THREE.WebGLRenderer({
  canvas: stage, antialias: true, alpha: false,
  preserveDrawingBuffer: true,
});
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
const camera = new THREE.PerspectiveCamera(44, 1, 0.01, 120);
camera.position.set(3.65, 3.25, 4.8);
camera.lookAt(0, 0, 0);
const controls = new OrbitControls(camera, stage);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.minDistance = 2.1;
controls.maxDistance = 12;
controls.target.set(0, 0, 0);
const guide = new THREE.GridHelper(6, 12, 0x506479, 0x243348);
guide.position.y = -0.12;
scene.add(guide);
const cardboard = new THREE.MeshStandardMaterial({
  color: 0xb98a69, roughness: 0.91, metalness: 0,
  side: THREE.DoubleSide,
});
const edgeMaterial = new THREE.LineBasicMaterial({
  color: 0x4f392d, transparent: true, opacity: 0.65,
});
for (const mesh of Object.values(runtime.meshes)) {
  const old = mesh.material;
  mesh.material = cardboard;
  if (Array.isArray(old)) old.forEach(material => material.dispose());
  else if (old && old !== cardboard) old.dispose();
  const outline = new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry), edgeMaterial);
  mesh.add(outline);
}
const obstacle = new THREE.Mesh(
  new THREE.BoxGeometry(0.13, 0.13, 0.13),
  new THREE.MeshStandardMaterial({color:0xe85e55, roughness:0.78}),
);
obstacle.visible = false;
scene.add(obstacle);
const collider = document.getElementById('collision-part');
const checkbox = document.getElementById('obstacle-enabled');
const statusBox = document.getElementById('status');
const statusTitle = document.getElementById('status-title');
const statusDetail = document.getElementById('status-detail');
const sliders = document.getElementById('sliders');
let lastEvaluation = null;
let previousWidth = 0, previousHeight = 0;

function setStatus(state, title, detail) {
  statusBox.dataset.state = state;
  statusTitle.textContent = title;
  statusDetail.textContent = detail;
}
function invalidateStatus() {
  lastEvaluation = null;
  document.getElementById('collision-timeline').replaceChildren();
  document.getElementById('collision-timeline').setAttribute('aria-label', 'No sampled collision timeline');
  document.getElementById('timeline-key').textContent = 'No angle samples yet.';
  setStatus('inactive', 'Not evaluated', 'Select a panel and evaluate its path.');
  scheduleRender();
}
function fitCanvas() {
  const bounds = stage.getBoundingClientRect();
  const width = Math.max(1, Math.floor(bounds.width));
  const height = Math.max(1, Math.floor(bounds.height));
  if (width !== previousWidth || height !== previousHeight) {
    previousWidth = width; previousHeight = height;
    renderer.setSize(width, height, false);
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
  }
}
function applyPose() {
  for (const id of ids) {
    runtime.hinges[id].rotation.y = THREE.MathUtils.degToRad(values[id]);
    const output = document.getElementById('value-' + id);
    const slider = document.getElementById('slider-' + id);
    if (output) output.value = values[id] + '°';
    if (slider) slider.value = String(values[id]);
  }
  root.updateMatrixWorld(true);
  document.getElementById('joint-angle').textContent =
    labels[collider.value] + ': ' + values[collider.value] + '°';
}
const playButton = document.getElementById('play');
let playbackFrame = null;
function stopAnimation() {
  if (playbackFrame !== null) window.cancelAnimationFrame(playbackFrame);
  playbackFrame = null;
  playButton.textContent = 'Animate fold';
  playButton.setAttribute('aria-pressed', 'false');
}
function animateFolds() {
  if (playbackFrame !== null) {
    stopAnimation();
    return;
  }
  // Respect operating-system reduced motion. This control still reaches the
  // same authored pose without imposing an animation on that user.
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    applyAll(referencePose);
    return;
  }
  const initial = {...values};
  const durationMs = 1700;
  let started = null;
  playButton.textContent = 'Stop animation';
  playButton.setAttribute('aria-pressed','true');
  invalidateStatus();
  const frame = now => {
    if (started === null) started = now;
    const progress = Math.min(1, Math.max(0, (now - started) / durationMs));
    // Smoothstep has zero endpoint velocity and does not imply physics.
    const eased = progress * progress * (3 - 2 * progress);
    for (const id of ids) {
      values[id] = Math.round((initial[id] +
        (referencePose[id] - initial[id]) * eased) * 1000) / 1000;
    }
    applyPose();
    if (progress >= 1) {
      for (const id of ids) values[id] = referencePose[id];
      applyPose();
      stopAnimation();
    } else playbackFrame = window.requestAnimationFrame(frame);
  };
  playbackFrame = window.requestAnimationFrame(frame);
}
function setFold(id, angle) {
  if (!ids.includes(id) || !Number.isFinite(angle) || angle < -180 || angle > 180) {
    throw new RangeError('unknown fold or out-of-range angle');
  }
  stopAnimation();
  values[id] = Math.round(angle * 1000) / 1000;
  applyPose();
  invalidateStatus();
  return getStatus();
}
function applyAll(pose) {
  stopAnimation();
  for (const id of ids) values[id] = pose[id] ?? 0;
  applyPose();
  invalidateStatus();
}
function placeObstacle() {
  if (!checkbox.checked) {
    obstacle.visible = false;
    invalidateStatus();
    return;
  }
  const id = collider.value;
  const hinge = runtime.hinges[id];
  const saved = hinge.rotation.y;
  try {
    hinge.rotation.y = Math.PI / 2;
    root.updateMatrixWorld(true);
    obstacle.position.copy(runtime.meshes[id].getWorldPosition(new THREE.Vector3()));
  } finally {
    hinge.rotation.y = saved;
    root.updateMatrixWorld(true);
  }
  obstacle.visible = true;
  invalidateStatus();
}
function evaluate() {
  const id = collider.value;
  const evaluationStart = performance.now();
  // The UI uses a bounded, responsive budget. Uncertainty must be surfaced,
  // not hidden by unlimited synchronous collision checks.
  const maxChecksPerTarget = 512;
  const maxDepth = 12;
  const segments = Math.max(1, Math.ceil(Math.abs(values[id]) / 5));
  const angles = Array.from({length:segments + 1}, (_, i) =>
    values[id] * i / segments);
  const targets = [{id:'carton floor', mesh:runtime.meshes.floor}];
  if (checkbox.checked) targets.push({id:'test obstacle', mesh:obstacle});
  const results = targets.map(target => {
    const sampled = sampleFold(runtime.hinges[id], runtime.meshes[id],
      target.mesh, angles);
    const adaptive = certifyFoldSweep(runtime.hinges[id], runtime.meshes[id],
      target.mesh, 0, values[id], {maxDepth, maxChecks:maxChecksPerTarget});
    return {
      id:target.id, status:adaptive.status, collision:adaptive.collision,
      sampledCollisions:sampled.collisionSamples,
      sampled:sampled.samples.map(entry=>Boolean(entry.penetrating)),
      evaluatedAngles:adaptive.evaluatedAngles,
      certifiedIntervals:adaptive.certifiedIntervals,
      unresolvedIntervals:adaptive.unresolvedIntervals,
    };
  });
  const hasCollision = results.some(result => result.status === 'collision');
  const hasUnresolved = results.some(result => result.status === 'unresolved');
  const status = hasCollision ? 'collision' :
    hasUnresolved ? 'unresolved' : 'certified-clear';
  const union = angles.map((angle, i) =>
    results.some(result => result.sampled[i]));
  const timeline = document.getElementById('collision-timeline');
  timeline.replaceChildren();
  for (let i = 0; i < angles.length; i++) {
    const cell = document.createElement('span');
    cell.dataset.hit = String(union[i]);
    cell.title = angles[i].toFixed(2) + '°: ' +
      (union[i] ? 'sampled overlap' : 'no sampled overlap');
    timeline.append(cell);
  }
  const hits = union.filter(Boolean).length;
  timeline.dataset.samples = String(angles.length);
  timeline.setAttribute('aria-label',
    hits + ' overlapping poses in ' + angles.length + ' sampled angles');
  document.getElementById('timeline-key').textContent =
    'Green: sampled separation · Red: sampled overlap (' +
    hits + '/' + angles.length +
    '). Gaps between samples are not ruled out by this strip.';
  const evaluationMs = Number((performance.now() - evaluationStart).toFixed(2));
  lastEvaluation = {
    component:id, targetDegrees:values[id], status, evaluationMs,
    maxChecksPerTarget, maxDepth,
    targets:results.map(({sampled, ...item}) => item),
    sampledCollisions:hits, sampledAngles:angles.length,
  };
  let detail;
  if (status === 'collision') {
    const hit = results.find(result => result.status === 'collision');
    detail = hit.id + ': overlap at ' + hit.collision.degrees.toFixed(2) +
      '° (' + hit.collision.overlap.toFixed(4) + ' units).';
  } else if (status === 'unresolved') {
    detail = 'At least one target has unresolved intervals; cannot certify safe motion.';
  } else {
    detail = 'All ' + results.length + ' checked rigid-box target(s) are clear ' +
      'under this limited static-target interval model.';
  }
  setStatus(status,
    status === 'collision' ? 'Collision detected' :
      status === 'certified-clear' ? 'Certified clear*' : 'Unresolved',
    detail + ' (' + evaluationMs.toFixed(1) + ' ms)');
  return lastEvaluation;
}
function getStatus() {
  return {
    angles: {...values},
    selected: collider.value,
    obstacleEnabled:checkbox.checked,
    obstaclePosition:obstacle.position.toArray(),
    obstacleVisible:obstacle.visible,
    lastEvaluation,
    drawCalls:renderer.info.render.calls,
    triangles:renderer.info.render.triangles,
    renderCount,
  };
}
let renderCount = 0;
function render() {
  fitCanvas();
  controls.update();
  renderer.render(scene, camera);
  renderCount++;
  document.getElementById('triangle-count').textContent =
    renderer.info.render.triangles.toLocaleString();
}
// Draw only when the scene, camera or viewport actually changes.
 // OrbitControls with damping dispatches change events until it settles;
 // the last frame does not perpetually schedule another idle GPU render.
let raf = null;
function scheduleRender() {
  if (raf !== null) return;
  raf = window.requestAnimationFrame(() => {
    raf = null;
    render();
  });
}
controls.addEventListener('change', scheduleRender);
for (const id of ids) {
  const label = document.createElement('label');
  label.className = 'slider-field';
  const head = document.createElement('span');
  head.className = 'field-head';
  const name = document.createElement('span');
  name.textContent = labels[id];
  const output = document.createElement('output');
  output.id = 'value-' + id;
  output.htmlFor = 'slider-' + id;
  head.append(name, output);
  const slider = document.createElement('input');
  slider.type = 'range';
  slider.min = '-180'; slider.max = '180'; slider.step = '1';
  slider.value = '0';
  slider.id = 'slider-' + id;
  slider.setAttribute('aria-label', labels[id] + ' angle');
  slider.addEventListener('input', () => setFold(id, Number(slider.value)));
  label.append(head, slider);
  sliders.append(label);
}
document.getElementById('rest').addEventListener('click', () => applyAll({}));
document.getElementById('pose').addEventListener('click', () => applyAll(referencePose));
playButton.addEventListener('click', animateFolds);
document.getElementById('check').addEventListener('click', evaluate);
checkbox.addEventListener('change', placeObstacle);
collider.addEventListener('change', placeObstacle);
document.getElementById('export').addEventListener('click', () => {
  const json = JSON.stringify({
    format:'img2threejs.hinge-lab-pose.v1', anglesDegrees:{...values},
    source:'study/hinge-real-photo-ab-20261019', collision:lastEvaluation
  }, null, 2) + '\n';
  const href = URL.createObjectURL(new Blob([json], {type:'application/json'}));
  const a = document.createElement('a');
  a.href = href; a.download = 'hinge-lab-pose.json';
  document.body.append(a); a.click(); a.remove();
  // Let the browser finish the download before releasing the local Blob.
  window.setTimeout(() => URL.revokeObjectURL(href), 10000);
});
const importFile = document.getElementById('import-file');
document.getElementById('import').addEventListener('click', () => importFile.click());
importFile.addEventListener('change', async () => {
  const file = importFile.files?.[0];
  if (!file) return;
  try {
    if (file.size < 2 || file.size > 64 * 1024) {
      throw new RangeError('Pose file size must be between 2 bytes and 64 KiB');
    }
    const parsed = JSON.parse(await file.text());
    if (parsed?.format !== 'img2threejs.hinge-lab-pose.v1' ||
        !parsed.anglesDegrees || typeof parsed.anglesDegrees !== 'object') {
      throw new Error('Unsupported pose format');
    }
    const angles = Object.fromEntries(ids.map(id => {
      const angle = parsed.anglesDegrees[id];
      if (typeof angle !== 'number' || !Number.isFinite(angle) ||
          angle < -180 || angle > 180) {
        throw new Error('Missing or invalid angle for ' + id);
      }
      return [id, angle];
    }));
    applyAll(angles);
    setStatus('inactive', 'Pose imported', file.name + ': four fold angles loaded locally.');
  } catch (error) {
    setStatus('unresolved', 'Import rejected', String(error.message || error));
  } finally {
    importFile.value = '';
  }
});
window.addEventListener('resize', scheduleRender);
applyAll({});
render();
window.__hingeLab = {
  getStatus, setFold, evaluate, animateFolds, stopAnimation, setObstacle(enabled, id) {
    if (id !== undefined) {
      if (!ids.includes(id)) throw new RangeError('unknown panel');
      collider.value = id;
    }
    checkbox.checked = Boolean(enabled);
    placeObstacle();
  },
  setPreset(kind) {
    if (kind === 'photo') applyAll(referencePose);
    else if (kind === 'flat') applyAll({});
    else throw new RangeError('unknown pose');
  },
  screenshot() {
    render();
    return stage.toDataURL('image/png');
  },
  dispose() {
    stopAnimation();
    controls.removeEventListener('change', scheduleRender);
    if (raf !== null) window.cancelAnimationFrame(raf);
    raf = null;
    controls.dispose();
    renderer.dispose();
  },
};
window.__hingeLabReady = true;
